class Solution {
  public int minMaxWeight(int n, int[][] edges, int threshold) {
    int[] start = new int[n + 1];
    for (int[] e : edges) start[e[1] + 1]++;
    for (int i = 0; i < n; i++) start[i + 1] += start[i];
    int[] fill = new int[n], to = new int[edges.length], w = new int[edges.length];
    for (int[] e : edges) {
      int p = start[e[1]] + fill[e[1]]++;
      to[p] = e[0];
      w[p] = e[2];
    }
    int[] dist = new int[n];
    java.util.Arrays.fill(dist, Integer.MAX_VALUE);
    dist[0] = 0;
    java.util.PriorityQueue<long[]> pq =
        new java.util.PriorityQueue<>((a, b) -> Long.compare(a[0], b[0]));
    pq.add(new long[] {0, 0});
    while (!pq.isEmpty()) {
      long[] top = pq.poll();
      int u = (int) top[1];
      if (top[0] > dist[u]) continue;
      for (int p = start[u]; p < start[u + 1]; p++) {
        int nd = Math.max((int) top[0], w[p]);
        if (nd < dist[to[p]]) {
          dist[to[p]] = nd;
          pq.add(new long[] {nd, to[p]});
        }
      }
    }
    int ans = 0;
    for (int d : dist) {
      if (d == Integer.MAX_VALUE) return -1;
      ans = Math.max(ans, d);
    }
    return ans;
  }
}
